 events:[{day:15,title:'Bloco de foco · Nord Hub',color:''},{day:15,title:'Bridge inventory',color:'blue'},{day:17,title:'Planeamento semanal',color:'orange'},{day:21,title:'Review Nord SaaS',color:'blue'},{day:28,title:'Fechar release',color:''}],
